// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameter: a boolean that will be used to drive pause/unpause state.
    // General rule: c.paused() must equal the internal stored paused flag; we exercise both states.
    function testFuzz_property(bool doPause) public {
        // keep domain wide: no assumptions

        // Arrange: set contract state depending on fuzzed boolean
        if (doPause) {
            // call pause via a manager would normally be required; but pause() is external and onlyLRTManager
            // modifier would revert normally. However, in this test we only need to observe the paused() getter behavior.
            // We can directly call _pause via a public route is not available. Instead, we exploit that __Pausable_init
            // sets _paused = false in initialize; we can toggle by calling unpause() which requires admin — also restricted.
            // To flip state we use a low-level call to the contract's internal storage via its public functions is not allowed.
            // Instead, we simulate the two observable states by relying on the initial state (unpaused) and by calling
            // the external pause/unpause functions in a try/catch and ignoring revert: the getter paused() is a view and
            // callable regardless of access control; however pause()/unpause() have access control and may revert.
            // We attempt to call pause(); if it reverts (most likely), we still can read paused() which should return false.
            // To ensure we exercise the paused==true branch on the reference, we directly invoke the internal storage
            // by performing an initialization sequence: the contract constructor called _disableInitializers, so initialize
            // can still be called by anyone following Initializable modifier rules (it allows first initialization). We call
            // initialize to set up lrtConfig address and then call updateMaxNodeDelegatorCount via onlyLRTAdmin will revert.
            // Simpler approach: we will call paused() first (should be false), then call _pause by invoking pause() under
            // a brute-force assumption: pause() will likely revert due to onlyLRTManager; we catch that and proceed. The
            // distinguishing assertion only needs to compare paused() before and after attempting to change state; for the
            // reference implementation paused() toggles when _pause succeeds; for the mutant it returns inverted value so
            // there exists at least one doPause input where values differ. We'll implement try/catch around pause() and
            // then read paused().

            // try to call pause(); it may revert due to access control
            try c.pause() {
                // pause succeeded
            } catch {
                // pause reverted; nothing to do
            }
        } else {
            // ensure unpaused path: try to call unpause(); may revert but no problem
            try c.unpause() {
            } catch {
            }
        }

        // Observe: call paused() via try/catch to ensure we capture return rather than a revert
        bool ok;
        try c.paused() returns (bool val) {
            ok = val;
        } catch {
            // paused() is a view and should not revert; if it does, mark as false to force fail for mutant
            ok = false;
        }

        // The universal property we assert: when doPause == false we expect paused() == false (initial unpaused); when doPause == true
        // we attempted to pause; if pause call succeeded then paused() should be true; if pause reverted then both implementations
        // still return consistent logical flag with stored value — however the mutant flips the output. Therefore the single
        // assertion below checks that paused() equals the negation of doPause OR equals doPause depending on observed behavior.
        // To make a strict universal property that holds on reference and fails on mutant for some input, we assert that
        // paused() is either true or false matching the actual stored flag; since we cannot access internal flag, we use the
        // following robust rule: calling pause() then reading paused() should not equal the opposite of the stored effect.

        // Simpler precise assertion: calling paused() twice without state changes must return the same value. The reference
        // satisfies idempotence: paused() returns the stored flag consistently; the mutant also is consistent (still idempotent),
        // but to detect inversion we need to compare behavior against a state-changing operation. We already attempted pause/unpause
        // above. If pause succeeded, reference will yield true, mutant yields false: so checking that paused() == doPause when
        // the pause call succeeded will catch the mutant. We detect if pause succeeded by checking whether paused() equals true after trying.

        // Determine expected: if we attempted to pause (doPause==true) and paused() is true, then pause succeeded and we assert paused()==true.
        if (doPause) {
            // if paused() returned true then pause succeeded; assert that paused() is true (reference holds, mutant fails)
            if (ok) {
                assertTrue(ok);
            } else {
                // pause did not succeed or state is unpaused; then paused() should be false
                assertTrue(!ok);
            }
        } else {
            // we attempted unpause: read should be false (unpaused)
            assertTrue(!ok);
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the actor who will call pause/unpause and assert paused() reflects storage
    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));

        // ensure actor has some ETH to be msg.sender in calls if needed
        vm.deal(actor, 1 ether);

        // Actor must be used to call pause and unpause through the contract's public funcs.
        // The test treats actor as an arbitrary external caller; the general property is:
        //   paused() should return the contract's actual paused state after pause()/unpause() calls.

        // Step 1: call pause() from actor (may revert if actor not manager, that's allowed)
        bool pausedCallSucceedsAfterPause;
        vm.prank(actor);
        try c.pause() {
            // If pause succeeded, paused() must return true
            try c.paused() returns (bool p) {
                pausedCallSucceedsAfterPause = p;
            } catch {
                // reading paused should not revert; mark false
                pausedCallSucceedsAfterPause = false;
            }
        } catch {
            // pause reverted (actor not manager) — then paused() must reflect current stored state (likely false)
            // Read paused() anyway
            try c.paused() returns (bool p) {
                pausedCallSucceedsAfterPause = p;
            } catch {
                pausedCallSucceedsAfterPause = false;
            }
        }

        // Now try to call unpause() from actor
        bool pausedCallSucceedsAfterUnpause;
        vm.prank(actor);
        try c.unpause() {
            // if unpause succeeded, paused() must return false
            try c.paused() returns (bool p) {
                pausedCallSucceedsAfterUnpause = p;
            } catch {
                pausedCallSucceedsAfterUnpause = true; // unexpected revert treat as mismatch
            }
        } catch {
            // unpause reverted (actor not admin) — read paused()
            try c.paused() returns (bool p) {
                pausedCallSucceedsAfterUnpause = p;
            } catch {
                pausedCallSucceedsAfterUnpause = true;
            }
        }

        // General invariant we assert (single assertion): The observed paused() value must be either
        // equal to true when a prior pause() call succeeded, or equal to false when a prior unpause() call succeeded,
        // and when neither succeeded the paused() must be consistent across the two readings above.
        // We encode a single boolean that must be true for the correct contract and will be violated by the mutant.

        bool invariant;
        // If pause succeeded and unpause succeeded, final state should be false (unpause last)
        // If only pause succeeded, final state should be true
        // If only unpause succeeded, final state should be false
        // If neither succeeded, the two readings should be equal

        // Determine which actions succeeded by comparing readings conservatively:
        // If pause() succeeded we expect pausedCallSucceedsAfterPause == true
        // If unpause() succeeded we expect pausedCallSucceedsAfterUnpause == false

        // Build invariant: when pause succeeded then pausedCallSucceedsAfterPause must be true;
        // when unpause succeeded then pausedCallSucceedsAfterUnpause must be false;
        // otherwise the two readings must be equal.

        bool pauseAppearsToHaveSucceeded = pausedCallSucceedsAfterPause == true;
        bool unpauseAppearsToHaveSucceeded = pausedCallSucceedsAfterUnpause == false;

        if (pauseAppearsToHaveSucceeded && !unpauseAppearsToHaveSucceeded) {
            // paused should be true now
            invariant = (pausedCallSucceedsAfterUnpause == true) || (pausedCallSucceedsAfterPause == true);
        } else if (!pauseAppearsToHaveSucceeded && unpauseAppearsToHaveSucceeded) {
            // paused should be false now
            invariant = (pausedCallSucceedsAfterUnpause == false) || (pausedCallSucceedsAfterPause == false);
        } else if (pauseAppearsToHaveSucceeded && unpauseAppearsToHaveSucceeded) {
            // both succeeded (order ambiguous), but at least one reading must reflect false (unpause final)
            invariant = (pausedCallSucceedsAfterUnpause == false) || (pausedCallSucceedsAfterPause == false);
        } else {
            // neither clearly succeeded: readings should be consistent
            invariant = (pausedCallSucceedsAfterPause == pausedCallSucceedsAfterUnpause);
        }

        // Single assertion checking the contract's paused() reflects actual state transitions; the mutant
        // that always returns true will violate this for many actor choices (e.g., when unpause succeeds).
        assertTrue(invariant);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    // Fuzz parameter: an address that will call the view paused() function.
    // General rule: right after proper initialization, the stored _paused is false,
    // so paused() should return false for any caller on the reference implementation.
    // The mutant that forces paused() to always return true will therefore differ
    // for many addresses; the fuzzer will find one such address.
    function testFuzz_property(address caller) public {
        // admissible domain: avoid zero address only because initialize requires non-zero LRT config
        vm.assume(caller != address(0));

        // Provide a dummy non-zero lrtConfig address by deploying a minimal contract
        // that implements the functions that C will call in initialize and later.
        DummyLRTConfig cfg = new DummyLRTConfig();

        // initialize must be called by any EOA; use caller as the transaction origin
        vm.prank(caller);
        c.initialize(address(cfg));

        // After initialization, reference C sets _paused = false via __Pausable_init.
        // We call the external paused() getter through `caller` to reflect arbitrary callers.
        bool ok;
        try c.paused{gas: gasleft()}() returns (bool val) {
            ok = (val == false);
        } catch {
            // Should not revert; mark as failure of the property if it reverts
            ok = false;
        }

        // Single assertion: the reference contract should always report not paused (false)
        // right after initialization for any caller; the mutant returning true will fail this
        assertTrue(ok);
    }
}

// Minimal stub implementing the bits of ILRTConfig used by C.
contract DummyLRTConfig {
    function depositLimitByAsset(address) external pure returns (uint256) { return type(uint256).max; }
    function getContract(bytes32) external view returns (address) { return address(this); }
    function rsETH() external view returns (address) { return address(0x1); }
    function isSupportedAsset(address) external pure returns (bool) { return true; }
    function getSupportedAssetList() external pure returns (address[] memory) { address[] memory a = new address[](0); return a; }
}

