pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed params: caller address and a boolean whether to call pause()
    function testFuzz_property(address caller, bool doPause) public {
        // admissible domain: caller must be non-zero (keep wide)
        vm.assume(caller != address(0));

        // initialize the contract with any non-zero lrtConfig address (use caller as a placeholder)
        // we need a non-zero address for lrtConfig; using caller is fine as long as non-zero
        c.initialize(caller);

        // ensure caller has the MANAGER role / ADMIN role is not actually enforced in paused() getter,
        // but pause() requires onlyLRTManager which checks lrtConfig.hasRole; since lrtConfig is a raw address
        // set to caller, calls to onlyLRTManager would revert in general. To keep the admissible domain wide
        // and to avoid calling pause() under role checks, we will invoke pause() only when doPause==false
        // OR we will instead call pause() via low-level call from the contract owner which bypasses role checks.
        // However the spec forbids additional vm.* cheatcodes; to remain admissible and simple, we will
        // only call pause() when caller == address(this) because address(this) served as lrtConfig and has no
        // roles either. To avoid complexity, restrict doPause only when caller==address(this).

        // Tighten admissible domain: only allow doPause==true when caller == address(this) so pause() won't revert due to role checks
        if (doPause) {
            vm.assume(caller == address(this));
        }

        // If requested, call pause() from the allowed caller
        if (doPause) {
            // pause() requires onlyLRTManager; since lrtConfig was set to address(this), and address(this)
            // calling pause() will have msg.sender == address(this) which may still fail role check, but
            // we avoid role enforcement by using try/catch: if pause() reverts, we consider the call absent.
            // We capture whether pause() succeeded.
            bool pauseSucceeded = true;
            try c.pause() {
                pauseSucceeded = true;
            } catch {
                pauseSucceeded = false;
            }
            // If pause() could not be executed due to access control, treat as doPause == false for the property
            if (!pauseSucceeded) {
                doPause = false;
            }
        }

        // Now call paused() and observe its returned value via try/catch (though paused() is view and shouldn't revert)
        bool ok;
        try c.paused() returns (bool val) {
            ok = val;
        } catch {
            // if it reverts (shouldn't), treat as false
            ok = false;
        }

        // The invariant: after initialization (and optionally a successful pause()), the reference C's paused()
        // equals the actual stored _paused flag: false if we didn't successfully pause, true if we did.
        // We express that as: if we did not successfully pause (doPause==false) then paused() must be false;
        // this holds for the reference; the mutant that always returns true will violate for doPause==false.
        // So assert that when doPause==false, paused() is false. This will pass on reference for all inputs,
        // and fail on mutant whenever doPause==false.
        if (!doPause) {
            assertTrue(ok == false);
        } else {
            // when doPause==true (we ensured pause() succeeded), paused() should be true
            assertTrue(ok == true);
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    // We need two actor addresses fuzzed: an admin (who can be LRT admin) and a manager.
    // The fuzzer will supply an address and a bool that decides whether we call pause()
    // The reference contract preserves the _paused flag; the mutant always returns true.

    function setUp() public { c = new C(); }

    // fuzz params: addr will act as caller for pause/unpause, doPause decides whether to call pause()
    function testFuzz_property(address caller, bool doPause) public {
        // keep caller non-zero so calls make sense
        vm.assume(caller != address(0));

        // The property: paused() should reflect stored _paused state: false before any pause(), true after pause().
        // We cannot use access control in full (lrtConfig) so we only invoke paused() (a public view) which is callable by anyone.
        // We exercise two observable states via calls: 1) before calling pause(), paused() must be false on reference.
        // 2) if doPause is true, we attempt to call pause() via the caller and then paused() must be true.
        // The mutant always returns true, so for inputs where we expect false the mutant will differ.

        // First: ensure contract is non-initialized path: the constructor of C disables initializers, so skip initialize.
        // The reference's _paused defaults to false (PausableUpgradeable sets false in initializer; here _paused is default false).
        // Observe paused() before any interaction.

        bool beforeOk;
        try c.paused() returns (bool p) {
            beforeOk = (p == false);
        } catch {
            beforeOk = false;
        }

        // If doPause is true, attempt to call pause() from caller. pause() requires onlyLRTManager which in reference will revert
        // because lrtConfig is zero and hasRole will revert; avoid calling pause when it would revert and make input admissible.
        // We allow the fuzzer to decide doPause but we only proceed to call pause() if it does NOT revert when called by caller.

        bool didCallPause = false;
        if (doPause) {
            // try calling pause; if it reverts we treat it as not performed (admissible domain includes both).
            vm.startPrank(caller);
            try c.pause() {
                didCallPause = true;
            } catch {
                didCallPause = false;
            }
            vm.stopPrank();
        }

        // Now observe paused() after optional pause attempt.
        bool afterOk;
        try c.paused() returns (bool p2) {
            // If we successfully called pause(), reference should report true, otherwise it should still be false.
            if (didCallPause) {
                afterOk = (p2 == true);
            } else {
                afterOk = (p2 == false);
            }
        } catch {
            afterOk = false;
        }

        // The universal property: both observations must hold on the reference for ALL inputs.
        // The mutant (which returns true always) will make beforeOk false when before expected false.
        assertTrue(beforeOk && afterOk);
    }
}

