pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameter: an address that will act as a manager/admin depending on calls
    function testFuzz_property(address admin, address manager) public {
        // keep addresses non-zero and distinct (wide bounds)
        vm.assume(admin != address(0));
        vm.assume(manager != address(0));

        // The reference contract's pause/unpause control is gated by access control via lrtConfig.
        // We cannot set lrtConfig here, but pause() and unpause() are public and will revert if caller
        // lacks role; however paused() is a public view that simply returns internal _paused flag.
        // We can still exercise the property by directly calling _pause/_unpause through the public
        // functions pause() and unpause using try/catch: if we manage to pause, paused() must return true,
        // if pause() reverts due to access control, paused() must remain false. The mutant always returns false,
        // so there exists inputs (when pause succeeds) that will make the mutant differ.

        bool pauseSucceeded = false;
        // attempt to pause as manager
        vm.prank(manager);
        try c.pause() {
            pauseSucceeded = true;
        } catch {}

        bool pausedView = c.paused();

        // The general rule: if pause() succeeded, paused() MUST be true; if pause() failed, paused() MUST be false (contract unchanged).
        // This single assertion captures that relation by comparing the observed paused() to whether pause() succeeded.
        assertTrue(pausedView == pauseSucceeded);
    }
}

