pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract MockLRTConfig {
    mapping(bytes32 => address) public store;
    function setContract(bytes32 k, address v) external { store[k]=v; }
    function getContract(bytes32 k) external view returns(address){ return store[k]; }
    function depositLimitByAsset(address) external pure returns (uint256){ return type(uint256).max; }
    function isSupportedAsset(address) external pure returns (bool){ return true; }
    function rsETH() external pure returns (address){ return address(0); }
}

contract MockAccessControl is MockLRTConfig {
    mapping(bytes32 => mapping(address=>bool)) public roles;
    function setRole(bytes32 r, address a, bool v) external { roles[r][a]=v; }
    function hasRole(bytes32 role, address account) external view returns(bool){ return roles[role][account]; }
}

contract InvMutTest is Test {
    C c;
    MockAccessControl cfg;

    function setUp() public {
        c = new C();
        cfg = new MockAccessControl();
        // initialize c with cfg as lrtConfig
        c.initialize(address(cfg));
        // grant MANAGER role to nobody by default; tests will fuzz one candidate
    }

    // General rule: after a caller with MANAGER role calls pause(), paused() must return true.
    // The mutant that always returns false will thus be detected when a fuzzed manager address is granted the MANAGER role and invokes pause().
    function testFuzz_property(address manager) public {
        // make sure manager is not zero and not this contract
        vm.assume(manager != address(0));
        vm.assume(manager != address(this));

        bytes32 MANAGER = keccak256("MANAGER");

        // grant manager role to the fuzzed address via the mock cfg
        cfg.setRole(MANAGER, manager, true);

        // ensure cfg is still the lrtConfig in c
        // now call pause() from the fuzzed manager
        vm.prank(manager);
        c.pause();

        // exactly one assertion: paused() must read true after pause when called by any legitimate manager
        bool p = c.paused();
        assertTrue(p);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz: managerAddr (candidate manager) and lrtConfigAddr (nonzero addr used to initialize)
    function testFuzz_property(address managerAddr, address lrtConfigAddr) public {
        // admissible domain: lrtConfigAddr must be non-zero because initialize checks non-zero
        vm.assume(lrtConfigAddr != address(0));
        // managerAddr must be non-zero EOA to act from
        vm.assume(managerAddr != address(0));

        // Initialize contract with provided lrtConfigAddr
        // initialize is external and has initializer modifier; call from some address
        vm.prank(address(1));
        c.initialize(lrtConfigAddr);

        // We need managerAddr to have the MANAGER role in lrtConfig. The contract C checks roles by calling
        // IAccessControl(address(lrtConfig)).hasRole(..., msg.sender). We cannot mutate an arbitrary lrtConfigAddr
        // so instead we rely on a practical approach: if managerAddr is the zero-address or if the lrtConfig has no code
        // the production check in C will likely return false — but the general rule only requires that when the caller
        // who does call pause() is considered a manager by lrtConfig, paused() should reflect the paused state.
        // To create an admissible manager according to C, deploy a tiny stub LRTConfig that gives MANAGER role to any caller
        // we want. We therefore ignore the provided lrtConfigAddr for role checks by replacing lrtConfig in storage
        // via calling updateLRTConfig — but updateLRTConfig requires onlyLRTAdmin. To avoid those complexities while still
        // following the spec, we instead deploy a simple LRTConfigStub and re-initialize C pointing to that stub.

        // Deploy a stub LRTConfig that treats any address as manager/admin and provides required functions
        LRTConfigStub stub = new LRTConfigStub();

        // Re-initialize another fresh contract instance to point to our stub and set up roles
        C c2 = new C();
        vm.prank(address(2));
        c2.initialize(address(stub));

        // Now act as managerAddr and call pause()
        vm.prank(managerAddr);
        // call pause() which requires onlyLRTManager — our stub will return true for hasRole
        c2.pause();

        // Observe paused() via public getter. The universal rule: for any managerAddr and admissible lrtConfigAddr,
        // after a manager calls pause(), paused() MUST return true on the reference implementation.
        bool isPaused;
        try c2.paused() returns (bool res) {
            isPaused = res;
        } catch {
            // If paused() reverts (shouldn't), record as false
            isPaused = false;
        }

        // Single assertion: reference must have paused()==true here; mutant (always returning false) will fail for many inputs
        assertTrue(isPaused);
    }
}

// Minimal LRTConfig stub that grants MANAGER role to any caller and implements the small interface used by C
contract LRTConfigStub {
    bytes32 public constant MANAGER = keccak256("MANAGER");
    function hasRole(bytes32, address) external pure returns (bool) {
        return true; // treat everyone as having role
    }
    function getContract(bytes32) external view returns (address) {
        return address(this);
    }
    function depositLimitByAsset(address) external pure returns (uint256) { return type(uint256).max; }
    function isSupportedAsset(address) external pure returns (bool) { return true; }
    function rsETH() external view returns (address) { return address(this); }
    function getLSTToken(bytes32) external view returns (address) { return address(this); }
    function getSupportedAssetList() external pure returns (address[] memory) { address[] memory a = new address[](0); return a; }
}

