pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

interface IAccessControlMinimal {
    function grantRole(bytes32 role, address account) external;
}

// Minimal LRTConfig stub that implements only what's needed by C:
contract LRTConfigStub is IAccessControlMinimal {
    address public managerRoleAdmin; // not used, just placeholder
    mapping(bytes32 => address) internal tokens;
    mapping(address => bool) public supported;
    mapping(bytes32 => address) public contracts;
    mapping(bytes32 => address) public roleGrantee; // simplistic

    bytes32 public constant MANAGER = keccak256("MANAGER");

    function setSupported(address asset, bool val) external {
        supported[asset] = val;
    }

    function isSupportedAsset(address asset) external view returns (bool) {
        return supported[asset];
    }

    function depositLimitByAsset(address) external pure returns (uint256) {
        return type(uint256).max / 2;
    }

    function rsETH() external view returns (address) {
        return address(0);
    }

    function getContract(bytes32 id) external view returns (address) {
        return contracts[id];
    }

    function setContract(bytes32 id, address addr) external {
        contracts[id] = addr;
    }

    // minimal AccessControl-like hasRole impl for onlyLRTManager
    mapping(bytes32 => mapping(address => bool)) internal roles;
    function grantRole(bytes32 role, address account) external override {
        roles[role][account] = true;
    }
    function hasRole(bytes32 role, address account) external view returns (bool) {
        return roles[role][account];
    }
}

contract InvMutTest is Test {
    C c;
    LRTConfigStub lrt;

    function setUp() public {
        c = new C();
        lrt = new LRTConfigStub();
    }

    // Fuzzed inputs: manager address and an arbitrary nonzero address used as the lrtConfig address
    function testFuzz_property(address manager, address maybeContract) public {
        // Domain restrictions: lrtConfig address must be nonzero (initialize checks nonzero)
        vm.assume(maybeContract != address(0));
        // manager should be a nonzero address
        vm.assume(manager != address(0));

