        // The mutant (missing assignment) will leave it 0, so this assertion will fail on that mutant for some input.
        if (ok) {
            // read the public getter and assert it equals 10
            assertTrue(c.maxNodeDelegatorCount() == 10);
        } else {
            // If initialize reverted (shouldn't for valid non-zero address in reference), then fail the test
            // by asserting false to ensure we only accept successful initialization paths for the property.
            assertTrue(false);
        }
    }
}
